int calculate_min_tour_length(int N, int M, int[] X) {
    int totalLength = 0;
    for (int i = 0; i < M; i++) {
        totalLength += Math.abs(X[(i + 1) % M] - X[i]);
    }

    int minTourLength = totalLength;
    for (int i = 0; i < M; i++) {
        int closedBridgeLength = Math.abs(X[(i + 1) % M] - X[i]);
        int newTourLength = totalLength - closedBridgeLength;
        minTourLength = Math.min(minTourLength, newTourLength);
    }

    return minTourLength;
}
